package kw.urtv.shared;
import android.os.Bundle;import java.time.*;import android.widget.*;
public class CalendarActivity extends TvPage {
 @Override public void onCreate(Bundle b){super.onCreate(b);Place p=Place.load(this);DisplayOptions o=DisplayOptions.load(this);CalendarData cal=new CalendarData(this);title("مواقيت الأيام القادمة",p.name+" · "+p.label());int[] corrections=new int[6];try(android.database.Cursor c=getContentResolver().query(DisplayOptions.URI,null,null,null,null)){if(c!=null&&c.moveToFirst()){corrections=PrayerCorrections.parse(android.net.Uri.parse("https://local/?"+c.getString(0)).getQueryParameter("adjust"));}}catch(Exception ignored){}
 note("التاريخ      الفجر      الشروق      الظهر      العصر      المغرب      العشاء");for(int i=0;i<7;i++){LocalDate day=LocalDate.now(p.zoneId()).plusDays(i);RegionSchedule.Result result=WorldPrayers.resolve(cal,day,p,corrections);StringBuilder line=new StringBuilder(o.numbers(day.toString()));if(result.times!=null)for(int t:result.times)line.append("     ").append(o.time(t));else line.append(" · غير متاح");note(line.toString());}note(p.officialEligible()?"العجيري للأيام المحفوظة؛ حساب الكويت عند غياب الجدول.":"مواقيت محسوبة · راجع جدول مسجدك عند وجود فرق.");addButton("رجوع",this::finish);}
}
